{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Duvelisib, which shares a chiral amino-heteroaryl and chlorinated aromatic core with the query, has an absolute oral bioavailability of 42% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Idelalisib, a structurally related PI3K inhibitor with a chiral amino-purine and halogenated heteroaromatic system, shows 34% oral bioavailability in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Vorasidenib, which contains a trifluoromethyl-bearing chiral amine and aminopyrimidine motif similar to the query, has 34% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Erlotinib, a lipophilic heteroaromatic kinase inhibitor, has an absolute oral bioavailability of 76% in cancer patients, demonstrating that this compound class can achieve high F despite challenging physicochemical features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "PK11195, a highly lipophilic heteroaromatic compound with no hydrogen-bond donors, has 33% absolute oral bioavailability in healthy volunteers, showing that high lipophilicity alone does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lapatinib, the closest lipophilic analogue with solubility concerns, was estimated at 30% oral bioavailability in a Phase I study, which is still above the 20% threshold; qualitative 'low' reports are less threshold-specific.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple transferable human oral bioavailability measurements for structurally related kinase inhibitors and lipophilic heteroaromatics fall at or above 30–76%, consistently supporting F ≥ 20% for the query. The unfavorable physicochemical prior is outweighed by this convergent experimental evidence, while qualitative low-bioavailability reports for lapatinib are contradicted by a numeric 30% estimate and by other analogues with higher F.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for the query molecule.",
    "Morgan similarities to the evidence molecules are low (0.16–0.26), limiting quantitative transferability.",
    "The effect of the pyridine N-oxide on solubility, permeability, and first-pass metabolism is not directly captured by the analogues.",
    "Lapatinib records are conflicting (qualitative low vs 30% estimate), creating uncertainty for the closest lipophilic analogue class."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

